import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p33_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_scale_batchnorm_forward(
    torch::Tensor x,
    torch::Tensor scale,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    double momentum,
    bool training
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_scale_batchnorm_forward", &fused_scale_batchnorm_forward,
          "Fused scale + BatchNorm1d forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// One block per feature channel c.
// Block processes all N rows for that channel.
// Shared memory layout: 2 * blockDim.x floats for mean/var Welford accumulation.

__global__ void fused_scale_bn_train_kernel(
    const float* __restrict__ x,       // [N, C]
    const float* __restrict__ scale,   // [C]
    const float* __restrict__ weight,  // [C] gamma
    const float* __restrict__ bias,    // [C] beta
    float* __restrict__ running_mean,  // [C]
    float* __restrict__ running_var,   // [C]
    float* __restrict__ out,           // [N, C]
    int N, int C,
    float eps, float momentum
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float sc = scale[c];
    float gam = weight[c];
    float bet = bias[c];

    // Welford online accumulation per thread
    float mean_acc = 0.f;
    float M2_acc  = 0.f;
    int   count   = 0;

    for (int n = threadIdx.x; n < N; n += blockDim.x) {
        float val = x[n * C + c] * sc;
        count++;
        float delta = val - mean_acc;
        mean_acc += delta / (float)count;
        float delta2 = val - mean_acc;
        M2_acc += delta * delta2;
    }

    // Warp-level Welford merge
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        float om  = __shfl_down_sync(mask, mean_acc, offset);
        float oM2 = __shfl_down_sync(mask, M2_acc,  offset);
        int   on  = __shfl_down_sync(mask, count,    offset);
        if (on > 0) {
            int total = count + on;
            float delta = om - mean_acc;
            mean_acc = (mean_acc * count + om * on) / (float)total;
            M2_acc  += oM2 + delta * delta * (float)count * (float)on / (float)total;
            count    = total;
        }
    }

    // Cross-warp reduction via shared memory
    extern __shared__ float smem[]; // 2 * nwarps floats + nwarps ints
    int warp_id  = threadIdx.x >> 5;
    int lane_id  = threadIdx.x & 31;
    int nwarps   = (blockDim.x + 31) >> 5;

    float* s_mean  = smem;           // [nwarps]
    float* s_M2    = smem + nwarps;  // [nwarps]
    int*   s_count = (int*)(smem + 2 * nwarps); // [nwarps]

    if (lane_id == 0) {
        s_mean[warp_id]  = mean_acc;
        s_M2[warp_id]    = M2_acc;
        s_count[warp_id] = count;
    }
    __syncthreads();

    if (warp_id == 0) {
        mean_acc = (lane_id < nwarps) ? s_mean[lane_id]  : 0.f;
        M2_acc   = (lane_id < nwarps) ? s_M2[lane_id]    : 0.f;
        count    = (lane_id < nwarps) ? s_count[lane_id] : 0;

        for (int offset = 16; offset > 0; offset >>= 1) {
            float om  = __shfl_down_sync(mask, mean_acc, offset);
            float oM2 = __shfl_down_sync(mask, M2_acc,  offset);
            int   on  = __shfl_down_sync(mask, count,    offset);
            if (on > 0) {
                int total = count + on;
                float delta = om - mean_acc;
                mean_acc = (mean_acc * count + om * on) / (float)total;
                M2_acc  += oM2 + delta * delta * (float)count * (float)on / (float)total;
                count    = total;
            }
        }

        if (lane_id == 0) {
            s_mean[0]  = mean_acc;
            s_M2[0]    = M2_acc;
            s_count[0] = count;
        }
    }
    __syncthreads();

    float batch_mean = s_mean[0];
    float batch_var  = (s_count[0] > 1) ? s_M2[0] / (float)s_count[0] : 0.f;
    float inv_std    = rsqrtf(batch_var + eps);

    // Update running stats (thread 0 only)
    if (threadIdx.x == 0) {
        running_mean[c] = (1.f - momentum) * running_mean[c] + momentum * batch_mean;
        // PyTorch uses unbiased variance for running_var
        float unbiased_var = (s_count[0] > 1) ? s_M2[0] / (float)(s_count[0] - 1) : 0.f;
        running_var[c]  = (1.f - momentum) * running_var[c]  + momentum * unbiased_var;
    }
    __syncthreads();

    // Normalize + affine
    for (int n = threadIdx.x; n < N; n += blockDim.x) {
        float val = x[n * C + c] * sc;
        out[n * C + c] = (val - batch_mean) * inv_std * gam + bet;
    }
}

__global__ void fused_scale_bn_eval_kernel(
    const float* __restrict__ x,
    const float* __restrict__ scale,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    float* __restrict__ out,
    int N, int C,
    float eps
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float sc      = scale[c];
    float gam     = weight[c];
    float bet     = bias[c];
    float mean    = running_mean[c];
    float inv_std = rsqrtf(running_var[c] + eps);
    float eff_sc  = sc * gam * inv_std;
    float eff_b   = bet - mean * eff_sc;

    for (int n = threadIdx.x; n < N; n += blockDim.x) {
        out[n * C + c] = x[n * C + c] * eff_sc + eff_b;
    }
}

torch::Tensor fused_scale_batchnorm_forward(
    torch::Tensor x,
    torch::Tensor scale,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    double momentum,
    bool training
) {
    TORCH_CHECK(x.is_cuda(),        "x must be CUDA");
    TORCH_CHECK(x.is_contiguous(),  "x must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2,       "x must be 2D [N, C]");

    int N = x.size(0);
    int C = x.size(1);

    auto out = torch::empty_like(x);

    int block_size = 128;
    if (training) {
        int nwarps = (block_size + 31) / 32;
        // shared: s_mean[nwarps] + s_M2[nwarps] + s_count[nwarps]
        int smem_bytes = nwarps * (2 * sizeof(float) + sizeof(int));
        fused_scale_bn_train_kernel<<<C, block_size, smem_bytes>>>(
            x.data_ptr<float>(),
            scale.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C, (float)eps, (float)momentum
        );
    } else {
        fused_scale_bn_eval_kernel<<<C, block_size>>>(
            x.data_ptr<float>(),
            scale.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C, (float)eps
        );
    }
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a GEMM (general matrix multiplication), applies scaling, 
        and then batch normalization.
        """
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.gemm = nn.Linear(in_features, out_features)
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.gemm(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        _fused_done = False
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 2:
            try:
                x = _stark_get_extension().fused_scale_batchnorm_forward(
                    x,
                    self.scale,
                    self.bn.weight,
                    self.bn.bias,
                    self.bn.running_mean,
                    self.bn.running_var,
                    float(self.bn.eps),
                    float(self.bn.momentum),
                    self.training,
                )
                _fused_done = True
            except Exception:
                x = x * self.scale
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if not _fused_done:
            x = self.bn(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

